-- Generated by scripts/build-construction-view-catalog.ts.
-- Publish only after compatible ask-bob and bob-worker runtimes.
begin;
do $construction_views_publication$
declare patches jsonb:=$construction_view_patches$[
  {
    "key": "tools.read_construction_draft",
    "definition": {
      "name": "read_construction_draft",
      "description": "Read a small construction overview, then exact revision-bound pages. Default view=overview; artifact_id:null lists drafts. parts shows definitions and placements; parameters includes exact formulas, normalized values and source pins; dependencies follows named part/node dependencies, bindings, joints and roles. ids:[] reads the whole selected view; named IDs select matching records (dependencies also follows ancestors/dependents). notes contains original description/questions. Result references reopen an earlier check/list/cut assessment without rerunning it: view=result, exact artifact/revision/result_id, section:null for all or a returned section name, ids:[]. Historical results do not prove current sources or grant write/drawing permission. Follow next_read and coverage before relying on omitted details. Each page preserves exact posts; an oversized post is explicitly split into JSON fragments with offsets. Never reconstruct a full construction merely to inspect or change one part.",
      "parameters": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "artifact_id": {
            "anyOf": [
              {
                "type": "string",
                "format": "uuid"
              },
              {
                "type": "null"
              }
            ]
          },
          "revision": {
            "anyOf": [
              {
                "type": "integer",
                "minimum": 1,
                "maximum": 999999999
              },
              {
                "type": "null"
              }
            ]
          },
          "after": {
            "anyOf": [
              {
                "type": "string",
                "maxLength": 240
              },
              {
                "type": "null"
              }
            ]
          },
          "view": {
            "type": "string",
            "enum": [
              "overview",
              "parts",
              "parameters",
              "bindings",
              "joints",
              "materials",
              "roles",
              "notes",
              "dependencies",
              "result"
            ]
          },
          "ids": {
            "type": "array",
            "maxItems": 20,
            "uniqueItems": true,
            "items": {
              "type": "string",
              "minLength": 1,
              "maxLength": 240
            }
          },
          "result_id": {
            "anyOf": [
              {
                "type": "string",
                "pattern": "^cs_[a-f0-9]{64}$"
              },
              {
                "type": "null"
              }
            ]
          },
          "section": {
            "anyOf": [
              {
                "type": "string",
                "minLength": 1,
                "maxLength": 120
              },
              {
                "type": "null"
              }
            ]
          }
        },
        "required": [
          "artifact_id",
          "revision",
          "after",
          "view",
          "ids",
          "result_id",
          "section"
        ]
      },
      "required_parameters": [
        "artifact_id",
        "revision",
        "after",
        "view",
        "ids",
        "result_id",
        "section"
      ],
      "optional_parameters": [],
      "additional_description": " Read a construction overview first, then only relevant revision-bound parts/parameters/dependencies/notes pages. Follow next_read and declared coverage; omitted constraints are not resolved. Checks, lists and cut assessments return small summaries and exact result references. Reopen those via read_construction_draft view=result with the exact result_id, artifact_id and revision; select a returned section for findings, quantities or limitations. Previously observed results survive worker restart and are historical, not current source approval. Request a new check when sources or geometry changed, not merely to recover its earlier output. For edits send only changed posts; server-side checks and drawing still read the full canonical construction."
    },
    "metadata": {
      "construction_view_version": 1
    }
  },
  {
    "key": "tools.check_construction_draft",
    "definition": {},
    "metadata": {}
  },
  {
    "key": "tools.derive_construction_lists",
    "definition": {},
    "metadata": {}
  },
  {
    "key": "tools.check_construction_cut_fit",
    "definition": {},
    "metadata": {}
  }
]$construction_view_patches$::jsonb;
 manual text:=$construction_view_manual$ Read a construction overview first, then only relevant revision-bound parts/parameters/dependencies/notes pages. Follow next_read and declared coverage; omitted constraints are not resolved. Checks, lists and cut assessments return small summaries and exact result references. Reopen those via read_construction_draft view=result with the exact result_id, artifact_id and revision; select a returned section for findings, quantities or limitations. Previously observed results survive worker restart and are historical, not current source approval. Request a new check when sources or geometry changed, not merely to recover its earlier output. For edits send only changed posts; server-side checks and drawing still read the full canonical construction.$construction_view_manual$;
 patch jsonb; prior shared.ai_prompt_versions; next_version integer; version_uuid uuid; definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 if not exists(select 1 from shared.ai_prompts where app='bob' and prompt_key='tools.edit_construction_parts' and active_version_id is not null) then raise exception 'construction_edits_publication_required'; end if;
 for patch in select value from jsonb_array_elements(patches||jsonb_build_array(jsonb_build_object('key','bob.workflows','definition','{}'::jsonb,'metadata','{}'::jsonb))) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=patch->>'key' for update of p;
  if not found then raise exception 'construction_views_dependency_missing'; end if;
  definition:=prior.definition||(patch->'definition');
  if patch->>'key'='bob.workflows' then
   definition:=jsonb_set(definition,'{workflows}',(select jsonb_agg(case when w->>'name'='workflow_construction_drawing' then jsonb_set(w,'{method}',to_jsonb((w->>'method')||manual)) else w end order by n) from jsonb_array_elements(definition->'workflows') with ordinality x(w,n)));
  elsif patch->>'key'<>'tools.read_construction_draft' then
   definition:=jsonb_set(definition,'{additional_description}',to_jsonb(coalesce(definition->>'additional_description','')||manual));
  end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','construction-views-v1')||(patch->'metadata'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 perform shared.activate_ai_catalog('bob',activation);
end $construction_views_publication$;
commit;
